const fs = require('fs');



function renderHTML(data) {
    let ttf = data.woff;
    let style = `<style>
        @font-face {
            font-family:"fonteditor";
            src: url(data:font/truetype;charset=utf-8;base64,${ttf});
        }
        .fonteditor { font-family: fonteditor; }
    </style>`;

    let rows = '<tr class="odd">';
    data.data.forEach(val => {
        console.log(val.value)
        rows += `<td class="info fonteditor">${val.value}</td>`;
    });
    rows += '</tr>';

    let html = `<html><head>${style}</head><body><table class="data">${rows}</table></body></html>`;
    fs.writeFileSync('html/13.html', html, 'utf8');
}



